SELECT id, username, password_hash, role, status, token_version, must_change_password
FROM `user`
WHERE id = #{id}

SELECT COUNT(*)
FROM `user`
WHERE email = #{email}
  AND id != #{id}

mapper.update:
UPDATE `user`
nickname = NULLIF(#{nickname}, ''), email = NULLIF(#{email}, ''), avatar = NULLIF(#{avatar}, ''), updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}

UPDATE `user`
nickname = NULLIF(#{nickname}, ''), email = NULLIF(#{email}, ''), role = #{role}, status = #{status}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
